public sealed class ScanProbe{public string Id{get;set;}=Guid.NewGuid().ToString("N");public string Payload{get;set;}="ut_probe_core";public string System{get;set;}="";public float Life{get;set;}=4000;public float Recall{get;set;}public float X{get;set;}public float Y{get;set;}public float Z{get;set;}public bool Connected{get;set;}=true;public bool Enabled{get;set;}=true;public float RangeAU{get;set;}=4;public float PlanX{get;set;}public float PlanY{get;set;}public float PlanZ{get;set;}public float PlanRange{get;set;}=4;public bool Planned{get;set;}}
public sealed class UtilitySite{public string TargetId{get;set;}="";public string Id{get;set;}="";public string System{get;set;}="";public string Kind{get;set;}="Data";public float Remaining{get;set;}=50000;public float X{get;set;}public float Y{get;set;}public float Z{get;set;}public float Signal{get;set;}public float EstimateX{get;set;}public float EstimateY{get;set;}public float EstimateZ{get;set;}public bool Completed{get;set;}public int Attempts{get;set;}public string Name{get;set;}="";public bool Anomaly{get;set;}public bool Ignored{get;set;}public bool Seen{get;set;}public int Difficulty{get;set;}=1;public int HitCount{get;set;}public float DeviationAU{get;set;}public string ResultShape{get;set;}="Sphere";public float PreviousSignal{get;set;}public string ContactGrid{get;set;}="";public string TargetName{get;set;}="";}
